  "revision_action": "keep",
  "supportive_card_ids": ["C06","C152","C153","C156","C159","C137","C118","C132","C131","C142","C200","C207","C09","C16","C25","C54","C11","C21","C24","C41","C51","C56","C59","C10","C36","C55"],
  "contradictory_card_ids": ["C251","C248","C233"],
  "prediction_basis_card_ids": ["C06","C152","C153","C156","C159","C137","C118","C132","C131","C142","C200","C207"],
  "claims": [
    {
      "claim": "Codeine, the closest morphinan analog with a direct absolute oral bioavailability record, had F = 80.5% in healthy subjects after oral and intravenous administration, supporting F ≥ 20% for hydromorphone, which shares the morphinan scaffold, 4,5-epoxy bridge, N-methyl group, and phenolic C3 substitution.",
      "card_ids": ["C06"]
    },
    {
      "claim": "L4 codeine records show >90% human fraction absorbed, rapid and almost complete intestinal absorption, high permeability (higher than metoprolol), and high solubility, supporting a favorable absorption component for the close morphinan analog hydromorphone.",
      "card_ids": ["C152","C153","C156","C159","C137","C118","C132"]
    },
    {
      "claim": "Morphine salts, the closest scaffold analogs to hydromorphone, are highly water-soluble (morphine sulfate 64.5 mg/mL; morphine hydrochloride 57.0 mg/mL), indicating no solubility barrier to reaching F ≥ 20%.",
      "card_ids": ["C131","C142"]
    },
    {
      "claim": "L5 morphine records show rapid absorption from the small intestine and Caco-2 transport much higher than low-permeability markers mannitol and PEG4000, with a literature bioavailability reported as 80%, providing gut-level mechanistic support for adequate absorption of the close morphinan analog.",
      "card_ids": ["C200","C207"]
    },
    {
      "claim": "L6 hepatic-clearance records are mostly for morphine in rat isolated perfused liver (e.g., low hepatic availability 0.13) and for other opioids; they indicate first-pass metabolism in the morphinan class but are species/assay-specific and not hydromorphone-specific, while codeine CLint is low (2.53 µL/min/mg) and human hepatocyte morphine CLint values are moderate; this does not affirm F < 20%.",
      "card_ids": ["C251","C248","C233","C221","C254","C238"]
    },
    {
      "claim": "Other opioid analgesics in the evidence set all exceeded the 20% threshold in the reported contexts: pentazocine ~0.68–0.70, meperidine 0.80–0.87, and meptazinol 27.9%, providing class-level consistency for opioid F ≥ 20%.",
      "card_ids": ["C09","C16","C25","C54","C11","C21","C24","C41","C51","C56","C59","C10","C36","C55"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C251","C248","C233","C221","C254","C238","C210","C232"]
    }
  ],
  "evidence_gaps": [
    "No direct hydromorphone absolute oral bioavailability or matched oral-versus-IV exposure record is present in the supplied cards.",
    "No hydromorphone-specific hepatic clearance or metabolic-stability data are supplied; L6 records are for morphine, codeine, dextromethorphan, and other opioids.",
    "Rat isolated perfused liver high extraction for morphine may not translate to human hydromorphone, which differs at C6 and C7-C8.",
    "No hydromorphone-specific gut-wall efflux or intestinal-metabolism data are supplied; L5 support is structural/class-based."
  ],
  "decision_summary": "Prediction remains high: codeine, the closest morphinan with a direct absolute F record, had F = 80.5%; codeine and morphine absorption/solubility evidence is favorable; L6 hepatic-clearance records show first-pass metabolism in the morphinan class but are species/assay-specific and not hydromorphone-specific, and no affirmative evidence supports F < 20%."
}

